constexpr auto equal() {
  int t = 0;
  return [t](auto obj) { return obj; };
}
template <typename F>
constexpr int bar (F) {
  return 42;
}

template <typename F>
constexpr auto compose(F f)
{
  return [f=f](int i) -> decltype(bar (f)) {
      return 42;
  };
}
